#include <iostream>
#include <limits>

// Recursive definition of factorial
unsigned long long factorial(unsigned int number) {
    // Base case: 0! = 1, 1! = 1
    if (number <= 1) {
        return 1ULL;
    }
    // Recursive step: n * (n - 1)!
    return number * factorial(number - 1);
}

int main() {
    // Demonstrate factorial up to overflow threshold (21! wraps around)
    for (unsigned int i = 0; i <= 5; ++i) {
        std::cout << i << "! = " << factorial(i) << "\n";
    }
    // Show 20! (valid) and 21! (wrapped overflow value)
    std::cout << "20! = " << factorial(20) << "\n";
    std::cout << "21! = " << factorial(21) << "\n";
    return 0;
}

#include <iostream>

// Recursive definition of Fibonacci sequence
unsigned long long fibonacci(unsigned int n) {
    // Base case: fibonacci(0) = 0, fibonacci(1) = 1
    if (n == 0 || n == 1) {
        return n;
    }
    // Recursive step: sum of two preceding terms
    return fibonacci(n - 1) + fibonacci(n - 2);
}

int main() {
    // Demonstrate sequence calculation for inputs shown in textbook pages 224-225
    const unsigned int test_values[] = {0, 1, 2, 3, 10, 20};
    for (unsigned int val : test_values) {
        std::cout << "Fibonacci(" << val << ") = " << fibonacci(val) << "\n";
    }
    return 0;
}
